package com.zeptopluse.controller; import com.zeptopluse.dto.*; import com.zeptopluse.service.AddressService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class AddressController { private final AddressService service; @GetMapping("/customers/{customerId}/addresses") public List<AddressResponse> list(@PathVariable Long customerId){return service.list(customerId);} @PostMapping("/customers/{customerId}/addresses") public ResponseEntity<AddressResponse> create(@PathVariable Long customerId,@Valid @RequestBody AddressRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(customerId,request));} @PutMapping("/addresses/{id}") public AddressResponse update(@PathVariable Long id,@Valid @RequestBody AddressRequest request){return service.update(id,request);} @DeleteMapping("/addresses/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }